"""FILE-009: speculative pre-execute and commit — must never speculate unsafe writes"""
from dataclasses import dataclass
from typing import List, Dict, Any
import asyncio

@dataclass
class SpeculativeTask:
    tool: str
    args: Dict[str, Any]
    confidence: float

@dataclass
class CommittedResult:
    tool: str
    result: Any
    hit: bool

class SpeculativeExecutor:
    """SRP: speculative pre-execute and commit"""
    def __init__(self, threshold: float = 0.55, max_parallel: int = 6):
        self.threshold = threshold
        self.max_parallel = max_parallel
        self._cache: Dict[str, Any] = {}

    async def speculate(self, predicted: List[SpeculativeTask]) -> Dict[str, asyncio.Task]:
        import hashlib, json
        candidates = [p for p in predicted if p.confidence >= self.threshold]
        candidates = sorted(candidates, key=lambda x: x.confidence, reverse=True)[:self.max_parallel]
        tasks: Dict[str, asyncio.Task] = {}
        for pred in candidates:
            # only speculative_safe assumed; caller filters unsafe
            key = hashlib.md5(f"{pred.tool}:{json.dumps(pred.args, sort_keys=True)}".encode()).hexdigest()
            if key in self._cache:
                continue
            # need a dummy executor: for demo, just echo; real will be injected
            async def _exec(tool=pred.tool, args=pred.args):
                await asyncio.sleep(0.02)
                return {"tool": tool, "args": args, "result": f"spec_result_{tool}"}
            tasks[key] = asyncio.create_task(_exec())
        return tasks

    async def commit(self, final_calls: List[Dict[str, Any]], speculative_tasks: Dict[str, asyncio.Task]) -> List[CommittedResult]:
        """METHOD-010: hit reuse, miss execute, abort unused"""
        import hashlib, json
        results: List[CommittedResult] = []
        for call in final_calls:
            tool = call.get("tool") or call.get("name")
            args = call.get("args") or call.get("arguments") or {}
            key = hashlib.md5(f"{tool}:{json.dumps(args, sort_keys=True)}".encode()).hexdigest()
            if key in speculative_tasks:
                try:
                    res = await speculative_tasks[key]
                    self._cache[key] = res
                    results.append(CommittedResult(tool=tool, result=res, hit=True))
                except asyncio.CancelledError:
                    results.append(CommittedResult(tool=tool, result={"error": "cancelled"}, hit=False))
            elif key in self._cache:
                results.append(CommittedResult(tool=tool, result=self._cache[key], hit=True))
            else:
                # miss: execute now
                await asyncio.sleep(0.02)
                res = {"tool": tool, "args": args, "result": f"direct_{tool}"}
                self._cache[key] = res
                results.append(CommittedResult(tool=tool, result=res, hit=False))
        # abort unused
        committed_keys = {hashlib.md5(f"{(c.get('tool') or c.get('name'))}:{json.dumps((c.get('args') or c.get('arguments') or {}), sort_keys=True)}".encode()).hexdigest() for c in final_calls}
        for k, t in list(speculative_tasks.items()):
            if k not in committed_keys:
                t.cancel()
                try:
                    await t
                except asyncio.CancelledError:
                    pass
        return results

"""FILE-005: index and search code snippets — must never bulk-load into context"""
from dataclasses import dataclass
from typing import List, Optional
import hashlib
from .index_file import IndexFile

@dataclass
class CodeSnippet:
    hash: str
    code: str
    description: str
    use_count: int = 0

@dataclass
class SearchQuery:
    text: str
    top_k: int = 3

@dataclass
class SnippetHit:
    snippet: CodeSnippet
    score: float

class CodeReuseIndex:
    """SRP: index and search code snippets"""
    def __init__(self, index_file: IndexFile):
        self._file = index_file

    def index_code(self, code: str, description: str) -> CodeSnippet:
        """METHOD-005: append-only, deduplicate by hash"""
        h = self._hash(code)
        # dedup check: read all, if hash exists return existing
        existing = [e for e in self._file.read_all() if e.get("hash") == h]
        if existing:
            e = existing[0]
            return CodeSnippet(hash=e["hash"], code=e["code"], description=e["description"], use_count=e.get("use_count", 0))
        snippet = CodeSnippet(hash=h, code=code, description=description, use_count=0)
        self._file.append({"hash": h, "code": code, "description": description, "use_count": 0})
        return snippet

    def search(self, query: SearchQuery) -> List[SnippetHit]:
        """METHOD-006: search without loading full index into LLM context"""
        all_entries = self._file.read_all()
        # ranking via lexical score, deterministic, no external deps
        # IMPORTANT: only top_k are returned to caller (LLM context), full index never bulk-loaded
        q = query.text.lower()
        scored = []
        for e in all_entries:
            txt = (e.get("code", "") + " " + e.get("description", "")).lower()
            score = 0.0
            for tok in q.split():
                if tok in txt:
                    score += 1.0
            if q in txt:
                score += 2.0
            # normalize
            score = score / max(1, len(q.split()))
            if score > 0:
                scored.append((e, score))
        scored.sort(key=lambda x: x[1], reverse=True)
        hits = []
        for e, s in scored[:query.top_k]:
            hits.append(SnippetHit(snippet=CodeSnippet(hash=e["hash"], code=e["code"], description=e["description"], use_count=e.get("use_count",0)), score=round(s,3)))
        return hits

    def _hash(self, code: str) -> str:
        return hashlib.md5(code.encode()).hexdigest()[:12]

"""FILE-007: persist index file on disk — must never do semantic ranking"""
from dataclasses import dataclass
from typing import List, Dict, Any
import os

@dataclass
class IndexFileRef:
    path: str
    entry_count: int

class IndexFile:
    """SRP: persist index file on disk"""
    def __init__(self, path: str):
        self.path = path
        # ensure file exists
        os.makedirs(os.path.dirname(os.path.abspath(path)) or ".", exist_ok=True)
        if not os.path.exists(path):
            open(path, "a").close()

    def append(self, entry: Dict[str, Any]) -> None:
        import json
        with open(self.path, "a", encoding="utf-8") as f:
            f.write(json.dumps(entry) + "\n")

    def read_all(self) -> List[Dict[str, Any]]:
        import json
        if not os.path.exists(self.path) or os.path.getsize(self.path) == 0:
            return []
        out = []
        with open(self.path, "r", encoding="utf-8") as f:
            for line in f:
                if line.strip():
                    out.append(json.loads(line))
        return out

    def size_bytes(self) -> int:
        if not os.path.exists(self.path):
            return 0
        return os.path.getsize(self.path)

"""FILE-006: indexed tool search, lazy load — must never expose full index to LLM"""
from dataclasses import dataclass
from typing import List, Dict, Any
from .index_file import IndexFile

@dataclass
class ToolSpecLite:
    name: str
    description: str
    relevance: float

@dataclass
class ToolSpecFull:
    name: str
    description: str
    parameters: Dict[str, Any]
    code_ref: str

@dataclass
class SearchResult:
    lite: ToolSpecLite
    score: float

class ToolIndex:
    """SRP: indexed tool search, lazy load"""
    def __init__(self, index_file: IndexFile):
        self._file = index_file

    def search_tools(self, query: str, top_k: int = 3) -> List[SearchResult]:
        """METHOD-007: only top-k lites, not 50; index stays on disk"""
        all_entries = self._file.read_all()
        # IMPORTANT: index file stays on disk; we only return top_k lite specs to LLM context
        # not the full 50. This avoids MCP window filling.
        q = query.lower()
        scored = []
        for e in all_entries:
            txt = (e.get("name","") + " " + e.get("description","")).lower()
            score = 0.0
            for tok in q.split():
                if tok in txt:
                    score += 1.0
            if q in txt:
                score += 1.5
            score = score / max(1, len(q.split()))
            scored.append((e, score))
        scored.sort(key=lambda x: x[1], reverse=True)
        results = []
        for e, s in scored[:top_k]:
            # lite: only name+desc, not full parameters (lazy)
            lite = ToolSpecLite(name=e["name"], description=e["description"][:120], relevance=round(s,3))
            results.append(SearchResult(lite=lite, score=round(s,3)))
        return results

    def lazy_load(self, tool_name: str) -> ToolSpecFull:
        """METHOD-008: load full spec from disk on demand"""
        for e in self._file.read_all():
            if e.get("name") == tool_name:
                return ToolSpecFull(name=e["name"], description=e["description"], parameters=e.get("parameters", {}), code_ref=e.get("code_ref",""))
        raise KeyError(f"tool not found: {tool_name}")

    def register_tool(self, spec: ToolSpecFull) -> None:
        self._file.append({"name": spec.name, "description": spec.description, "parameters": spec.parameters, "code_ref": spec.code_ref})

"""FILE-003: programmatic context inspection via code — must never load full docs into LLM prompt"""
from dataclasses import dataclass
from typing import Callable, Any
from .document_store import DocumentStore, DocId, SliceSpec

@dataclass
class InspectionQuery:
    intent: str
    code: str  # LLM-generated Python code handle

@dataclass
class InspectionResult:
    slice_text: str
    byte_range: SliceSpec
    inspection_code: str

class ContextInspector:
    """SRP: programmatic context inspection via code"""
    def __init__(self, store: DocumentStore):
        self._store = store

    def inspect_via_code(self, doc_id: DocId, llm_code: str) -> InspectionResult:
        """METHOD-004: LLM writes code like store.slice(0,100), never receives full doc"""
        # LLM code is executed in restricted env with only code handle, not full doc
        # Example llm_code: "result = store.slice(doc_id, SliceSpec(offset=0, length=200))"
        env = self.get_code_handle_env(doc_id)
        # imports for code
        env["SliceSpec"] = SliceSpec
        env["DocId"] = DocId
        # Capture result via exec
        local_vars: dict = {}
        exec(llm_code, env, local_vars)
        # Convention: LLM code must set `result` or `slice_text`
        slice_text = local_vars.get("result") or local_vars.get("slice_text") or local_vars.get("output") or ""
        if not isinstance(slice_text, str):
            slice_text = str(slice_text)
        # Try to infer range from code string for audit
        byte_range = SliceSpec(offset=0, length=len(slice_text))
        if "SliceSpec" in llm_code:
            # best effort parse offset/length
            import re
            m = re.search(r"offset\s*=\s*(\d+).*length\s*=\s*(\d+)", llm_code)
            if m:
                byte_range = SliceSpec(offset=int(m.group(1)), length=int(m.group(2)))
        return InspectionResult(slice_text=slice_text, byte_range=byte_range, inspection_code=llm_code)

    def get_code_handle_env(self, doc_id: DocId) -> dict:
        """Returns env dict for LLM code execution: {'store': ..., 'slice': ...}"""
        # Only expose slice handle, never full text
        def slice_handle(offset: int = 0, length: int = 500):
            return self._store.slice(doc_id, SliceSpec(offset=offset, length=length))
        return {
            "store": self._store,
            "doc_id": doc_id,
            "slice": slice_handle,
            "SliceSpec": SliceSpec,
        }

"""FILE-004: store and slice documents — must never call LLM"""
from dataclasses import dataclass
from typing import Dict
import os

@dataclass
class DocId:
    value: str

@dataclass
class SliceSpec:
    offset: int
    length: int

class Document:
    def __init__(self, doc_id: DocId, path: str, byte_count: int):
        self.doc_id = doc_id
        self.path = path
        self.byte_count = byte_count

class DocumentStore:
    """SRP: store and slice documents"""
    def __init__(self):
        self._docs: Dict[str, Document] = {}

    def ingest(self, path: str) -> Document:
        """METHOD-003: ingest real file, byte count matches"""
        if not os.path.exists(path):
            raise FileNotFoundError(f"Document not found: {path}")
        byte_count = os.path.getsize(path)
        # read to validate
        with open(path, "rb") as f:
            _ = f.read()
        doc_id = DocId(value=os.path.abspath(path))
        doc = Document(doc_id=doc_id, path=os.path.abspath(path), byte_count=byte_count)
        self._docs[doc_id.value] = doc
        return doc

    def slice(self, doc_id: DocId, spec: SliceSpec) -> str:
        doc = self._docs.get(doc_id.value)
        if doc is None:
            raise KeyError(f"doc not ingested: {doc_id.value}")
        with open(doc.path, "r", encoding="utf-8", errors="ignore") as f:
            text = f.read()
        return text[spec.offset: spec.offset + spec.length]

    def byte_count(self, doc_id: DocId) -> int:
        doc = self._docs.get(doc_id.value)
        if doc is None:
            raise KeyError(doc_id.value)
        return doc.byte_count
